/* From Uiverse.io by nikk7007 - Tags: button */
.__UIV_SCOPE__ .button {
 --color: #00A97F;
 padding: 0.8em 1.7em;
 background-color: transparent;
 border-radius: .3em;
 position: relative;
 overflow: hidden;
 cursor: pointer;
 transition: .5s;
 font-weight: 400;
 font-size: 17px;
 border: 1px solid;
 font-family: inherit;
 text-transform: uppercase;
 color: var(--color);
 z-index: 1;
}

.__UIV_SCOPE__ .button::before, .__UIV_SCOPE__ .button::after {
 content: '';
 display: block;
 width: 50px;
 height: 50px;
 transform: translate(-50%, -50%);
 position: absolute;
 border-radius: 50%;
 z-index: -1;
 background-color: var(--color);
 transition: 1s ease;
}

.__UIV_SCOPE__ .button::before {
 top: -1em;
 left: -1em;
}

.__UIV_SCOPE__ .button::after {
 left: calc(100% + 1em);
 top: calc(100% + 1em);
}

.__UIV_SCOPE__ .button:hover::before, .__UIV_SCOPE__ .button:hover::after {
 height: 410px;
 width: 410px;
}

.__UIV_SCOPE__ .button:hover {
 color: rgb(10, 25, 30);
}

.__UIV_SCOPE__ .button:active {
 filter: brightness(.8);
}
